package vn.edu.eaut.lab8.model; import java.io.Serializable; public class Sach implements Serializable {private int id,namXuatBan;private String tenSach,tacGia; public Sach(){} public Sach(int i,String t,String a,int n){id=i;tenSach=t;tacGia=a;namXuatBan=n;} public int getId(){return id;}public void setId(int v){id=v;}public String getTenSach(){return tenSach;}public void setTenSach(String v){tenSach=v;}public String getTacGia(){return tacGia;}public void setTacGia(String v){tacGia=v;}public int getNamXuatBan(){return namXuatBan;}public void setNamXuatBan(int v){namXuatBan=v;}}
